import React, { useState, useRef } from 'react';
import { View, Text, TouchableOpacity, Dimensions, TextInput, TextInputProps } from 'react-native';

import { useContexState } from '../../../hooks/context';
import { styles } from './styles';

import api from '../../../services/api';

import { Entypo } from '@expo/vector-icons';

export function RegisterMenu() {
    const [value, onChangeText] = useState('Buscar');

    const ref = useRef<TextInput>(null);
    const [LoadAddCart, setLoadAddCart] = useState(false);

    const {
        shoppingCartItem,
        selectedNumber,
        paymentMenuActive
    } = useContexState();

    const {
        setShoppingCartItem,
        setPaymentMenuActive
    } = useContexState();


    function filterString(text: string) {
        if (text === text.replace(/[^0-9]/g, '')) onChangeText(text);
    };


    function Input({ style }: TextInputProps) {
        return (
            <TextInput
                style={[styles.input, style]}
                onChangeText={text => {/*filterString(text)*/ }}
                //  value={value}
                maxLength={4}
                keyboardType={'numeric'}
                autoCorrect={false}
                placeholderTextColor='#fff'
                onFocus={() => {
                    ref.current?.clear();
                    onChangeText('');
                }}
                ref={ref}
            />

        )
    }





    function Menu() {


        return (
            <>
                <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center', marginVertical: 6 }}>{<Text style={{ fontSize: 40 }}>15</Text>}{"\n"}NÚMEROS POR APENAS{"\n"}{<Text style={{ fontSize: 25 }}>R$ 121,00</Text>}</Text>
                <View  >
                    <Text style={{ color: '#fff', fontSize: 20, marginVertical: 5 }}>Nome Completo*</Text>
                    <Input />
                </View>

                <View  >
                    <Text style={{ color: '#fff', fontSize: 20, marginVertical: 5 }}>Telefone*</Text>
                    <View><Input style={{width: 50}} /> <Input /></View>
                </View>

                <TouchableOpacity style={styles.buttonPay} >
                    <Text style={{ color: '#fff', fontSize: 30, textAlign: 'center' }}>Concluir</Text>
                    <Text style={{ color: '#fff', fontSize: 16, textAlign: 'center' }}>Link de Pagamento com PIX</Text>
                </TouchableOpacity>
            </>
        );
    }


    return (
        true ?
            <>
                <TouchableOpacity onPress={() => {
                    setPaymentMenuActive(false);
                }} style={{
                    position: 'absolute',
                    alignItems: 'center',
                    justifyContent: 'center',
                    minWidth: Dimensions.get('window').width,
                    minHeight: Dimensions.get('window').height
                }} />

                <View style={styles.container} >
                    <Menu />
                </View>
            </> : null
    );
};
